module sequence_detector (
    input clk,
    input in,
    input reset,
    output match);parameter IDLE=0, S1=1, S10=2, S101=3;
    reg [1:0] state;
    reg [1:0] next;

    always_comb begin
        case (state)
            IDLE: next = in ? S1 : IDLE;
            S1: next = in ? S1 : S10;
            S10: next = in ? S101 : IDLE;
            S101: next = in ? S1 : S10;
        endcase
    end

    always @(posedge clk) begin
        if (reset) state <= IDLE;
        else state <= next;
    end

    assign match = (state == S101);

endmodule

