  output [3:0] count; 
  assign count[3] = ~|mantissa[9:2]; 
  assign count[2] = |mantissa[9:2] & ~|mantissa[9:6]; 
  assign count[1] = count[3] & ~|mantissa[1:0] | ~count[3] & (~count[2] & ~|mantissa[9:8] | count[2] & ~|mantissa[5:4]); 
  assign count[0] = (mantissa[9:8] == 2'b01) | 
