module top_module(
    input clk,
    input rst,
    output reg red,
    output reg yellow,
    output reg green
);// Define the states of the state machine
parameter STATE_RED = 2'b00;
parameter STATE_YELLOW = 2'b01;
parameter STATE_GREEN = 2'b10;

// Define the state and counter variables
reg [1:0] state;
reg [5:0] counter;

// Initialize the state and counter variables
initial begin
    state = STATE_RED;
    counter = 0;
end

// Define the state machine
always @(posedge clk, posedge rst) begin
    if (rst) begin
        state <= STATE_RED;
        counter <= 0;
    end else begin
        case (state)
            STATE_RED: begin
                red <= 1;
                yellow <= 0;
                green <= 0;
                counter <= counter + 1;
                if (counter == 20) begin
                    state <= STATE_YELLOW;
                    counter <= 0;
                end
            end
            STATE_YELLOW: begin
                red <= 0;
                yellow <= 1;
                green <= 0;
                counter <= counter + 1;
                if (counter == 5) begin
                    state <= STATE_GREEN;
                    counter <= 0;
                end
            end
            STATE_GREEN: begin
                red <= 0;
                yellow <= 0;
                green <= 1;
                counter <= counter + 1;
                if (counter == 15) begin
                    state <= STATE_RED;
                    counter <= 0;
                end
            end
        endcase
    end
end

endmodule

