        else if (en == 1 && r_w == 0) 
        begin
            data = dbus_in;
            m[abus] = dbus_in;
        end
        else if (en == 1 && r_w == 1) 
            data = m[abus];
        else
            data = 8'hZZ;
    end
    assign dbus_out = data;endmodule

