Design a clock delay circuit that introduces a programmable delay to an input clock signal. The module takes an 8-bit input representing the desired delay count. It produces a single output clock signal that goes high after the specified number of clock cycles have elapsed, effectively delaying the input clock signal by the programmed amount. The output will remain low until the counter reaches the defined delay value, at which point the delayed clock output is set high for one clock cycle, then reset for subsequent counts.
module top_module(
    input wire clk,
    input wire [7:0] delay,
    output wire clk_delayed
);

code:
module top_module(
    input wire clk,
    input wire [7:0] delay,
    output wire clk_delayed
);reg [7:0] counter;
    reg delayed_clk;

    always @(posedge clk) begin
        if (counter == delay) begin
            delayed_clk <= 1;
            counter <= 0;
        end
        else begin
            delayed_clk <= 0;
            counter <= counter + 1;
        end
    end

    assign clk_delayed = delayed_clk;

endmodule

