module top_module(
  input clk,
  input rst,
  input [n-1:0] in,
  output reg [n-1:0] out
);parameter n = 16; // number of bits for input and output signals
parameter m = 8; // number of bits for filter coefficients

// Filter coefficients
reg [m-1:0] a0 = 8'h1; // a0 coefficient
reg [m-1:0] a1 = 8'h2; // a1 coefficient
reg [m-1:0] b1 = 8'h3; // b1 coefficient

// Shift registers for input and output samples
reg [n-1:0] x [1:0]; // input samples
reg [n-1:0] y [1:0]; // output samples

integer i;

always @(posedge clk or posedge rst) begin
  if (rst) begin
    // Reset the shift registers and output
    for (i = 0; i < 2; i = i + 1) begin
      x[i] <= 0;
      y[i] <= 0;
    end
    out <= 0;
  end else begin
    // Shift input samples
    x[1] <= x[0];
    x[0] <= in;

    // Shift output samples
    y[1] <= y[0];

    // Calculate output sample
    y[0] <= (a0 * x[0] + a1 * x[1] - b1 * y[1]) >>> m;

    // Update output
    out <= y[0];
  end
end

endmodule

