module top_module(clk_w, clk_r, wen, x_addr_w, y_addr_w, x_addr_r, y_addr_r, data_w, data_r);parameter WIDTH = 1024; // VGA display width
  parameter HEIGHT = 768; // VGA display height
  parameter BITS_PER_PIXEL = 24; // number of bits per pixel

  reg [BITS_PER_PIXEL-1:0] buffer [0:WIDTH-1][0:HEIGHT-1]; // buffer to store pixel values

  input clk_w;
  input clk_r;
  input wen;
  input [9:0] x_addr_w;
  input [9:0] y_addr_w;
  input [9:0] x_addr_r;
  input [9:0] y_addr_r;
  input [BITS_PER_PIXEL-1:0] data_w;
  output [BITS_PER_PIXEL-1:0] data_r;

  // write operation
  always @(posedge clk_w) begin
    if (wen) begin
      buffer[x_addr_w][y_addr_w] <= data_w;
    end
  end

  // read operation
  assign data_r = buffer[x_addr_r][y_addr_r];

endmodule

