module elevator_controller (
	input clk,
	input resetn,
	input up,
	input down,
	output reg [1:0] floor);

	parameter FLOOR_0=2'b00, FLOOR_1=2'b01, FLOOR_2=2'b10, FLOOR_3=2'b11;
	reg [1:0] state, next_state;

	always @(posedge clk) begin
		if (~resetn) state <= FLOOR_0;
		else state <= next_state;
	end

	always_comb begin
		case (state)
			FLOOR_0: next_state = up ? FLOOR_1 : FLOOR_0;
			FLOOR_1: next_state = down ? FLOOR_0 : (up ? FLOOR_2 : FLOOR_1);
			FLOOR_2: next_state = down ? FLOOR_1 : (up ? FLOOR_3 : FLOOR_2);
			FLOOR_3: next_state = down ? FLOOR_2 : FLOOR_3;
			default: next_state = FLOOR_0;
		endcase
	end

	always @(state) begin
		floor = state;
	end
endmodule

