module top_module(
    input wire[3:0] value,
    input wire auxValue,
    output reg[6:0] segments
    );always @ (*) begin
    if (auxValue) begin
        case (value)
            4'h0: segments = 7'h00; 
            4'h1: segments = 7'h73; 
            4'h2: segments = 7'h78; 
            4'h3: segments = 7'h50; 
            4'h4: segments = 7'h1C; 
            4'h5: segments = 7'h76; 
            4'h6: segments = 7'h38; 
            default: segments = 7'b0;
        endcase
    end
    else begin 
        case (value)
            4'h0: segments = 7'h3F; 
            4'h1: segments = 7'h06; 
            4'h2: segments = 7'h5B; 
            4'h3: segments = 7'h4F; 
