module vending_machine_controller (
  input coin,
  input select,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg dispense);parameter IDLE=0, READY=1, DISPENSE=2;

    always_comb begin
        case (state)
            IDLE: next_state = coin ? READY : IDLE;
            READY: next_state = select ? DISPENSE : READY;
            DISPENSE: next_state = IDLE;
        endcase
    end

    always_comb begin
        case (state)
            IDLE: dispense = 0;
            READY: dispense = 0;
            DISPENSE: dispense = 1;
        endcase
    end

endmodule

